permission_denials.command:
python3 -c "
import json,re,sys
p='journals/2026-08-19-routine-handover-check.md'
t=open(p).read()
fm=t.split('---',2)[1]
try:
    import yaml
except ImportError:
    print('no pyyaml'); sys.exit(0)
d=yaml.safe_load(fm)
ev={e['id'] for e in d['evidence']}
print('evidence ids:',len(ev),'dupes:',len(d['evidence'])-len(ev))
bad=[]
for h in d['hypotheses']:
    for r in h['evidence_for']+h['evidence_against']:
        if r not in ev: bad.append((h['id'],r))
    if not (h['evidence_for'] or h['evidence_against']): bad.append((h['id'],'NO CITATION'))
for lf in d.get('latent_findings',[]):
    for r in lf['evidence']:
        if r not in ev: bad.append(('latent',r))
print('dangling refs:',bad)
print('verdict:',d['verdict'],'| root_cause present:','root_cause' in d)
from datetime import datetime
s=datetime.fromisoformat(d['investigation']['started'].replace('Z','+00:00'))
c=datetime.fromisoformat(d['investigation']['concluded'].replace('Z','+00:00'))
print('wall clock delta:',int((c-s).total_seconds()),'declared:',d['usage']['wall_clock_seconds'])
print('id matches filename:',d['investigation']['id']=='2026-08-19-routine-handover-check')
print('states:',[(h['id'],h['state']) for h in d['hypotheses']])
"
